  TextView value=settingLabel(Integer.toString(settings.fontWeight));value.setGravity(Gravity.CENTER);
  minus.setEnabled(settings.fontWeight>0);plus.setEnabled(settings.fontWeight<ReaderSettings.FONT_WEIGHT_MAX);
  slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){
   boolean tracking;
   public void onStartTrackingTouch(SeekBar bar){tracking=true;}
   public void onProgressChanged(SeekBar bar,int progress,boolean user){int amount=progress*ReaderSettings.FONT_WEIGHT_STEP;value.setText(Integer.toString(amount));bar.setContentDescription("文字粗细："+amount);minus.setEnabled(progress>0);plus.setEnabled(progress<bar.getMax());if(user&&!tracking)applyFontWeight(amount);}
   public void onStopTrackingTouch(SeekBar bar){tracking=false;applyFontWeight(bar.getProgress()*ReaderSettings.FONT_WEIGHT_STEP);}
  });
  row.addView(minus,new LinearLayout.LayoutParams(d(40),d(40)));row.addView(slider,new LinearLayout.LayoutParams(0,d(48),1));row.addView(plus,new LinearLayout.LayoutParams(d(40),d(40)));row.addView(value,new LinearLayout.LayoutParams(d(34),d(40)));
