 // Keep the three Tomato reader actions in the same columns in both panels.
 LinearLayout readerTools(boolean inSettings){
  LinearLayout tools=row(this);
  for(String label:new String[]{"目录",settings.night?"日间":"夜间","设置","书签"}){
   TextView tool=text(this,label,10,ink());tool.setGravity(Gravity.CENTER);
   tool.setIncludeFontPadding(false);tool.setCompoundDrawablePadding(d(5));
   tool.setContentDescription(label);tool.setPadding(0,d(13),0,0);
   tool.setCompoundDrawablesWithIntrinsicBounds(null,new SettingsToolIcon(label,ink(),d(20),inSettings&&label.equals("设置")),null,null);
   tool.setOnClickListener(v->{if(label.equals("目录"))catalog(false);else if(label.equals("书签"))catalog(true);else if(label.equals("设置")){if(inSettings)closePanel();else showSettings();}else{settings.night=!settings.night;settings.save();surface.invalidatePageImages();surface.invalidate();if(inSettings)showSettings();else showMenu();}});
   tools.addView(tool,new LinearLayout.LayoutParams(0,d(56),1));
  }
  return tools;
 }
